async markPaidIfPending(id: string, chargeId: string): Promise<boolean> {
  const r = this.#db
    .prepare(
      `UPDATE orders SET status = 'PAID', charge_id = ?, updated_at = ?
       WHERE id = ? AND status = 'PENDING_PAYMENT'`,
    )
    .run(chargeId, this.#now().toISOString(), id);
  return r.changes === 1;
}
